func tsNodeCryptoKeyType(key any)string{switch key.(type){case *rsa.PrivateKey,*rsa.PublicKey:return "rsa";case *ecdsa.PrivateKey,*ecdsa.PublicKey:return "ec";case ed25519.PrivateKey,ed25519.PublicKey:return "ed25519";case *ecdh.PrivateKey,*ecdh.PublicKey:return "ec";case *tsNodeCryptoDHState:return "dh";default:return ""}}
